Definition mrun {R} (o : mem) (t : Malloc.M R) : Malloc.M (mem * R) := prun pans_mem pupd_mem o t.

Lemma mrun_ret {R} o (r : R) : mrun o (SRet r) = SRet (o, r).
Proof.
ltac2:(KReplay.run1 (kr_t_MallocTree ()) ["CANSEC1"] "h01Rh11oh21rp;2p;1p;4p100V\p6051000R0g005:R1p4p710R2p8p200R3P0p8P3P2p8g00WWj24TP1j13Tg00X7j40Tg00XWj41Tg00IUj22Tg00RLR1f1R2f2R0,41R4#3g00YNg00QGP4P1P0P2f0R4C0C1'2X22X11X03P0P2P4O3W2W1X03o"). Qed.
